	if len(body) != 3 {
		t.Fatalf("%d body rows, want 3", len(body))
	}
	for i, l := range body {
		inner := strings.TrimSpace(strings.Trim(l, "│┃|"))
		// the border glyph is one cell wide; look at what follows it
		_, after, _ := strings.Cut(l, strings.Trim(l, " ")[:1])
		_ = after
		hasMark := strings.Contains(l, theme.IconCircleSmall+" ")
		if want := i == 2; hasMark != want {
			t.Errorf("row %d mark = %v, want %v: %q", i, hasMark, want, l)
		}
		if i != 2 && !strings.Contains(l, "  ") {
			t.Errorf("row %d lacks the two-space prefix: %q", i, l)
		}
		_ = inner
	}
